	-- Step 27: Ogre Warbeads
	-- {npc:11501} King Gordok
	["A Dire Maul North run with a group of five: kill every Gordok ogre on the way to {npc:11501}."] = "Ein Lauf durch Düsterbruch Nord mit einer Gruppe aus fünf: Töte jeden Gordok-Oger auf dem Weg zu {npc:11501}.",
	-- {npc:16032} Falrin Treeshaper
	["{npc:16032}: choose your reward"] = "{npc:16032}: Wähle deine Belohnung",

	-- Step 28: The Instigator's Enchantment
	-- {npc:16032} Falrin Treeshaper · {item:22224} Jeering Spectre's Essence · {npc:11496} Immol'thar · {area:2057} Scholomance · {item:13704} Skeleton Key
	-- plural, as words: Eldreth Seethers = {npc:11469} Eldreth Seether · Dark Runes = {item:20520} Dark Rune · Large Brilliant Shards = {item:14344} Large Brilliant Shard
	["{npc:16032} wants a {item:22224} (the Eldreth ghosts of Dire Maul West, best the Eldreth Seethers, and the invisible spectres around {npc:11496}'s prison), 4 Dark Runes (the necromancers and summoners of {area:2057}, whose gate opens to a {item:13704}: one in the group is enough; or the auction house) and 8 Large Brilliant Shards (enchanters, or the auction house)."] = "{npc:16032} will {item:22224} (die Eldreth-Geister von Dire Maul West, am besten die Eldreth-Brodler, und die unsichtbaren Gespenster um das Gefängnis von {npc:11496}), 4 Dunkle Runen (die Nekromanten und Beschwörer von {area:2057}, dessen Tor sich mit {item:13704} öffnet: einer in der Gruppe genügt; oder das Auktionshaus) und 8 Große glänzende Splitter (Verzauberer oder das Auktionshaus).",

	-- Step 29: The Challenge
	-- {npc:16032} Falrin Treeshaper · {item:21986} Banner of Provocation · {area:1584} Blackrock Depths
	["{npc:16032} finishes the {item:21986}: plant it in the Ring of Law in {area:1584}."] = "{npc:16032} stellt {item:21986} fertig: Platziere es im Ring des Gesetzes in {area:1584}.",

	-- Step 30: Blackrock Depths: the Ring of Law
	-- {area:1584} Blackrock Depths
	["{area:1584}: the Ring of Law"] = "{area:1584}: der Ring des Gesetzes",
	-- {area:1584} Blackrock Depths · {area:254} Blackrock Mountain · {zone:1427} Searing Gorge · {zone:1428} Burning Steppes · {npc:10096} High Justice Grimstone · {item:21986} Banner of Provocation · {npc:16059} Theldren · {item:22047} Top Piece of Lord Valthalak's Amulet
	["{area:1584} is the dungeon inside {area:254}, between the {zone:1427} and the {zone:1428}; a group of five. Walk into the Ring of Law so {npc:10096} sentences you, and while he reads the sentence plant the {item:21986} in the middle of the ring. After the first wave, {npc:16059} and his gladiators come instead of the usual boss: five elites who fight like players (crowd control, dispels, no taunts). Kill them all; {npc:16059} drops the {item:22047}."] = "{area:1584} ist der Dungeon im Inneren von {area:254}, zwischen {zone:1427} und {zone:1428}; eine Gruppe aus fünf. Geh in den Ring des Gesetzes, damit {npc:10096} dich verurteilt, und während er das Urteil verliest, stell {item:21986} in die Mitte des Rings. Nach der ersten Welle kommen statt des üblichen Bosses {npc:16059} und seine Gladiatoren: fünf Elites, die wie Spieler kämpfen (Kontrolleffekte, Bannungen, kein Spott). Töte sie alle; {npc:16059} lässt {item:22047} fallen.",
	-- {item:21986} Banner of Provocation
	["{item:21986}, in the ring"] = "{item:21986}, im Ring",

	-- Step 31: Anthion Harmon: Anthion's Parting Words
	-- {npc:16016} Anthion Harmon · {area:2279} Stratholme · {quest:84185} Anthion's Parting Words · {item:16704} Dreadmist Sandals · {npc:10436} Baroness Anastari · {item:16699} Dreadmist Leggings · {npc:10440} Baron Rivendare · {item:16701} Dreadmist Mantle · {npc:10503} Jandice Barov · {area:2057} Scholomance
	["Back to {npc:16016} at {area:2279}'s gate (Ghost Revealer). {quest:84185} takes your {item:16704}: {npc:10436} in {area:2279} (about 18%), your {item:16699}: {npc:10440} in {area:2279} (about 10%), and your {item:16701}: {npc:10503} in {area:2057} (about 17%)."] = "Zurück zu {npc:16016} am Tor von {area:2279} (Geisterenthüller). {quest:84185} nimmt dein {item:16704}: {npc:10436} in {area:2279} (etwa 18 %), dein {item:16699}: {npc:10440} in {area:2279} (etwa 10 %), und dein {item:16701}: {npc:10503} in {area:2057} (etwa 17 %).",

	-- Step 34: Bodley
	-- {npc:16033} Bodley · {area:1583} Blackrock Spire · {area:254} Blackrock Mountain · {quest:8961} Three Kings of Flame · {item:21987} Incendicite of Incendius · {npc:9017} Lord Incendius · {area:1584} Blackrock Depths · {item:21988} Ember of Emberseer · {npc:9816} Pyroguard Emberseer · {item:21989} Cinder of Cynders · {npc:15206} Duke of Cynders · {zone:1451} Silithus · {item:22014} Hallowed Brazier · {faction:529} Argent Dawn
	["{npc:16033}'s ghost stands on the ledge before the {area:1583} portal, high inside {area:254}: use the Ghost Revealer there. {quest:8961} wants the {item:21987} ({npc:9017} in {area:1584}), the {item:21988} ({npc:9816} in Upper Blackrock Spire), the {item:21989} (the {npc:15206} in {zone:1451}) and a {item:22014} from the {faction:529}."] = "Der Geist von {npc:16033} steht auf dem Felsvorsprung vor dem Portal nach {area:1583}, hoch oben in {area:254}: Benutze dort den Geisterenthüller. {quest:8961} verlangt {item:21987} ({npc:9017} in {area:1584}), {item:21988} ({npc:9816} in der Oberen Schwarzfelsspitze), {item:21989} ({npc:15206} in {zone:1451}) und {item:22014} von {faction:529}.",

	-- Step 36: Honored with the Argent Dawn
	-- {faction:529} Argent Dawn
	["Honored with the {faction:529}"] = "Wohlwollend bei {faction:529}",
	-- {item:22014} Hallowed Brazier · {item:12846} Argent Dawn Commission · {npc:10840} Argent Officer Pureheart · {area:3197} Chillwind Camp · {npc:10839} Argent Officer Garush · {area:813} Bulwark · {npc:11039} Duke Nicholas Zverenhoff · {area:2268} Light's Hope Chapel · {area:2279} Stratholme · {area:2057} Scholomance
	["The {item:22014} is sold only to Honored. Take the {item:12846} ({npc:10840} at {area:3197}, {npc:10839} at the {area:813}, or {npc:11039} at {area:2268}) and wear it: Scourgestones then drop from the Scourge, and the Argent officers take them back for reputation. Every Scourge kill in the Plaguelands counts, {area:2279}'s and {area:2057}'s undead give 5 each up to Honored, and {area:2268}'s dungeon quests give 100-200 each. Polestar's Argent Dawn Reputation guide (Reputation) walks it step by step."] = "{item:22014} wird erst ab Wohlwollend verkauft. Hol dir {item:12846} ({npc:10840} in {area:3197}, {npc:10839} bei {area:813} oder {npc:11039} in {area:2268}) und leg es an: Dann lässt die Geißel Geißelsteine fallen, und die Offiziere der Argentumdämmerung nehmen sie gegen Ruf zurück. Jeder Geißel-Kill in den Pestländern zählt, die Untoten in {area:2279} und {area:2057} geben bis Wohlwollend je 5, und die Dungeonquests von {area:2268} je 100-200. Polestars Guide zum Ruf bei der Argentumdämmerung (Ruf) führt dich Schritt für Schritt hindurch.",

	-- Step 37: Hallowed Brazier
	-- {object:2160} The Argent Dawn · {area:2268} Light's Hope Chapel · {area:3197} Chillwind Camp · {area:813} Bulwark
	["{object:2160} quartermasters ({area:2268}, {area:3197}, the {area:813}) sell it: 133 gold 33 silver, less with your reputation discount."] = "Rüstmeister von {object:2160} ({area:2268}, {area:3197}, {area:813}) verkaufen es: 133 Gold 33 Silber, weniger mit deinem Rufrabatt.",

	-- Step 38: Blackrock Depths and Upper Blackrock Spire
	-- {area:1584} Blackrock Depths
	["{area:1584} and Upper Blackrock Spire"] = "{area:1584} und Obere Schwarzfelsspitze",
	-- {npc:9017} Lord Incendius · {object:174825} Black Anvil (no name in this language: may be words) · {area:1584} Blackrock Depths · {npc:9816} Pyroguard Emberseer
	["{npc:9017} guards the {object:174825} in {area:1584} (a group of five). {npc:9816} is the first boss of Upper Blackrock Spire, a group of up to ten. Each player with the quest loots their own."] = "{npc:9017} bewacht {object:174825} in {area:1584} (eine Gruppe aus fünf). {npc:9816} ist der erste Boss der Oberen Schwarzfelsspitze, eine Gruppe aus bis zu zehn. Jeder Spieler mit der Quest plündert seinen eigenen.",
	-- {npc:9816} Pyroguard Emberseer
	["{npc:9816}, Upper Blackrock Spire"] = "{npc:9816}, Obere Schwarzfelsspitze",

	-- Step 39: Duke of Cynders
	-- {zone:1451} Silithus · {item:20422} Twilight Cultist Medallion of Station · {npc:15282} Aurel Goldleaf · {area:3425} Cenarion Hold · {item:14344} Large Brilliant Shard · {item:20432} Signet of Beckoning: Fire · {npc:15206} Duke of Cynders
	-- plural, as words: Greater Wind Stones = {object:180466} Greater Wind Stone · Abyssal Crests = {item:20513} Abyssal Crest
	["The Duke (level 62 elite, bring a group of five) only comes when someone summons him at one of the Twilight's Greater Wind Stones in {zone:1451}: the summoner wears the full Twilight Cultist set (Cowl, Mantle and Robe, from the Twilight cultists of the {zone:1451} camps), carries a {item:20422} ({npc:15282} at {area:3425}: three Abyssal Crests from summoned Templars and a {item:14344}) and a {item:20432}, which calls the {npc:15206} rather than a random Duke. Joining someone else's summon is the quick way: every player with the quest loots their own Cinder."] = "Der Fürst (Stufe 62 Elite, bring eine Gruppe aus fünf mit) kommt nur, wenn ihn jemand an einem der Großen Windsteine des Schattenhammers in {zone:1451} beschwört: Der Beschwörer trägt das komplette Kultistenset des Schattenhammers (Gugel, Mantel und Robe, von den Kultisten des Schattenhammers in den Lagern von {zone:1451}), hat {item:20422} ({npc:15282} in {area:3425}: drei Abyssische Wappen von beschworenen Templern und {item:14344}) und {item:20432} dabei, das {npc:15206} statt eines zufälligen Fürsten ruft. Bei der Beschwörung eines anderen mitzumachen ist der schnelle Weg: Jeder Spieler mit der Quest plündert seine eigene Schlacke.",

	-- Step 40: Bodley: Components of Importance
	-- {npc:16033} Bodley
	["{npc:16033}'s next task depends on your class: the piece the summoning brazier needs."] = "Die nächste Aufgabe von {npc:16033} hängt von deiner Klasse ab: das Teil, das die Beschwörungskohlenpfanne braucht.",

	-- Step 42: Components of Importance: Starbreeze Village Relic
	-- {zone:1452} Winterspring · {area:2255} Everlook · {item:22227} Starbreeze Village Relic
	-- plural, as words: Frostmaul Giants = {npc:7428} Frostmaul Giant · Frostmaul Preservers = {npc:7429} Frostmaul Preserver
	["At the Frostmaul giants' gorge in southern {zone:1452}, south of {area:2255}, Frostmaul Giants and Frostmaul Preservers (level 59-60 elites) drop the {item:22227} (a rare drop: it can take dozens of kills). They are elites: bring a friend or two unless your gear is good. It drops only while you have the quest; everyone in the group with it can loot one."] = "In der Schlucht der Frostschlundriesen im südlichen {zone:1452}, südlich von {area:2255}, lassen Frostschlundriesen und Frostschlundbewahrer (Elite der Stufe 59-60) {item:22227} fallen (ein seltener Drop: es kann Dutzende Kills dauern). Sie sind Elite: Nimm ein, zwei Freunde mit, außer deine Ausrüstung ist gut. Es droppt nur, solange du die Quest hast; jeder in der Gruppe mit der Quest kann eines plündern.",

	-- Step 44: The Left Piece of Lord Valthalak's Amulet
	-- {npc:16033} Bodley · {item:22050} Brazier of Beckoning
	["{npc:16033} gives you a {item:22050}."] = "{npc:16033} gibt dir {item:22050}.",

	-- Step 45: The Left Piece of Lord Valthalak's Amulet: Isalien
	-- {npc:16033} Bodley · {item:22050} Brazier of Beckoning · {npc:16097} Isalien · {npc:11492} Alzzin the Wildshaper
	["A dungeon run for a group of five. {npc:16033}'s {item:22050} calls {npc:16097} to the shrine by {npc:11492} at the end of Dire Maul East: clear the area first. Use the brazier there, kill {npc:16097} and loot the piece. She is an elite priestess spirit with a hippogryph at her side and strong heals: interrupt her or drain her mana. Keep the brazier: {npc:16033} wants it back with the piece."] = "Ein Dungeonlauf für eine Gruppe aus fünf. {item:22050} von {npc:16033} ruft {npc:16097} zum Schrein bei {npc:11492} am Ende von Düsterbruch Ost: Räume zuerst die Umgebung. Benutze dort die Kohlenpfanne, töte {npc:16097} und plündere das Stück. Sie ist ein Elite-Priesterinnengeist mit einem Hippogryphen an ihrer Seite und starken Heilungen: Unterbrich sie oder entziehe ihr Mana. Behalte die Kohlenpfanne: {npc:16033} will sie mit dem Stück zurück.",
	-- {item:22050} Brazier of Beckoning · {npc:16097} Isalien
	["{item:22050}: summons {npc:16097}"] = "{item:22050}: beschwört {npc:16097}",

	-- Step 48: Bloodkelp
	-- {area:2079} Alcaz Island · {zone:1445} Dustwallow Marsh · {npc:16072} Tidelord Rrurgaz
	["The Strashaz naga of {area:2079}, off the north-east coast of {zone:1445}, carry it (level 59-61 elites, and {npc:16072} at 62): bring a friend or two. The Baskets of Bloodkelp on the island give 1 to 3 each without a fight. Swim over from the coast north of Theramore; elite hydras roam the water."] = "Die Naga der Strashaz auf {area:2079} vor der Nordostküste von {zone:1445} tragen es bei sich (Elite der Stufe 59-61, und {npc:16072} mit 62): Nimm ein, zwei Freunde mit. Die Blutseetangkörbe auf der Insel geben je 1 bis 3 ohne Kampf. Schwimm von der Küste nördlich von Theramore hinüber; Elite-Hydren streifen durchs Wasser.",

	-- Step 51: More Components of Importance: Soul Ashes of the Banished
	-- {area:896} Purgation Isle · {zone:1424} Hillsbrad Foothills · {item:22229} Soul Ashes of the Banished
	["At {area:896}, the island off the south coast of the {zone:1424}, the Condemned and Cursed undead (level 57-60 elites), thickest by the tower on the hill drop the {item:22229} (usually 5 to 15 kills; they stun, so a healer or dispeller helps). They are elites: bring a friend or two unless your gear is good. It drops only while you have the quest; everyone in the group with it can loot one."] = "Auf {area:896}, der Insel vor der Südküste der {zone:1424}, lassen die verdammten und verfluchten Untoten (Elite der Stufe 57-60), am dichtesten beim Turm auf dem Hügel, {item:22229} fallen (meist 5 bis 15 Kills; sie betäuben, ein Heiler oder Banner hilft also). Sie sind Elite: Nimm ein, zwei Freunde mit, außer deine Ausrüstung ist gut. Es droppt nur, solange du die Quest hast; jeder in der Gruppe mit der Quest kann eines plündern.",

	-- Step 54: The Right Piece of Lord Valthalak's Amulet: Kormok
	-- {npc:16033} Bodley · {item:22052} Brazier of Beckoning · {npc:16118} Kormok · {npc:10508} Ras Frostwhisper · {area:2057} Scholomance · {spell:27688} Bone Shield · {item:21984} Left Piece of Lord Valthalak's Amulet · {item:22048} Lord Valthalak's Amulet
	["A dungeon run for a group of five. {npc:16033}'s {item:22052} calls {npc:16118} to {npc:10508}'s room in {area:2057}: clear the room first. Use the brazier there, kill {npc:16118} and loot the piece. He is an elite ogre spirit who keeps raising skeletons: dispel or purge his {spell:27688} and burn him down. After a wipe he stays up: come back without summoning again. Keep the brazier: {npc:16033} wants it back with the piece. Then use the {item:21984} ({npc:16033} gave it back to you) to join the pieces into {item:22048}."] = "Ein Dungeonlauf für eine Gruppe aus fünf. {item:22052} von {npc:16033} ruft {npc:16118} in den Raum von {npc:10508} in {area:2057}: Räume zuerst den Raum. Benutze dort die Kohlenpfanne, töte {npc:16118} und plündere das Stück. Er ist ein Elite-Ogergeist, der ständig Skelette erweckt: Banne oder reinige {spell:27688} und brenn ihn nieder. Nach einem Wipe bleibt er stehen: Komm zurück, ohne ihn erneut zu beschwören. Behalte die Kohlenpfanne: {npc:16033} will sie mit dem Stück zurück. Benutze dann {item:21984} ({npc:16033} hat es dir zurückgegeben), um die Stücke zu {item:22048} zusammenzufügen.",
	-- {item:22052} Brazier of Beckoning · {npc:16118} Kormok
	["{item:22052}: summons {npc:16118}"] = "{item:22052}: beschwört {npc:16118}",
	-- {item:21984} Left Piece of Lord Valthalak's Amulet
	["{item:21984}: joins the pieces"] = "{item:21984}: fügt die Teile zusammen",

	-- Step 56: Final Preparations
	-- {area:1583} Blackrock Spire · {item:13512} Flask of Supreme Power
	-- plural, as words: Blackrock Bracers = {item:22138} Blackrock Bracer · Scarshield Grunts = {npc:9043} Scarshield Grunt
	["40 Blackrock Bracers from the Blackrock orcs of {area:1583} (the Scarshield Grunts in the mountain's halls outside the portal, level 53-54 elites, drop them most often; Upper {area:1583}'s orcs better than Lower's), only while you have the quest, and a {item:13512} (alchemists make it at an alchemy lab; or the auction house)."] = "40 Schwarzfelsarmschienen von den Schwarzfelsorcs in {area:1583} (die Grunzer der Narbenschilde in den Hallen des Berges vor dem Portal, Elite der Stufe 53-54, lassen sie am häufigsten fallen; die Orcs in der Oberen {area:1583} sind besser als die in der Unteren), nur solange du die Quest hast, und {item:13512} (Alchemisten stellen es an einem Alchemielabor her; oder im Auktionshaus).",

	-- Step 58: Upper Blackrock Spire: Lord Valthalak
	-- {area:1583} Blackrock Spire · {npc:16042} Lord Valthalak
	["Upper {area:1583}: {npc:16042}"] = "Obere {area:1583}: {npc:16042}",
	-- {npc:10430} The Beast · {item:22056} Brazier of Beckoning · {npc:16042} Lord Valthalak · {item:22048} Lord Valthalak's Amulet · {quest:8996} Return to Bodley
	["A raid of up to ten in Upper Blackrock Spire. Clear to {npc:10430}'s room and kill {npc:10430}, then use the {item:22056} there to call {npc:16042} (level 63 boss). Kill his shades quickly; in his last phase he hits the whole room hard. Use {item:22048} on his corpse: his spirit appears. Give him the amulet, then take {quest:8996} from him."] = "Ein Schlachtzug mit bis zu zehn Spielern in der Oberen Schwarzfelsspitze. Räume bis zum Raum von {npc:10430}, töte {npc:10430} und benutze dort {item:22056}, um {npc:16042} zu rufen (Boss der Stufe 63). Töte seine Schemen schnell; in seiner letzten Phase trifft er den ganzen Raum hart. Benutze {item:22048} auf seinem Leichnam: Sein Geist erscheint. Gib ihm das Amulett und nimm dann {quest:8996} bei ihm an.",
	-- {item:22056} Brazier of Beckoning · {npc:10430} The Beast
	["{item:22056}, in {npc:10430}'s room"] = "{item:22056}, im Raum von {npc:10430}",
	-- {item:22048} Lord Valthalak's Amulet
	["{item:22048}, on his corpse"] = "{item:22048}, auf seinem Leichnam",

	-- Step 59: Bodley: Back to the Beginning
	-- {npc:16033} Bodley · {item:22056} Brazier of Beckoning
	["Hand {npc:16033} the {item:22056}."] = "Gib {npc:16033} {item:22056}.",

	-- Step 60: Deliana: Saving the Best for Last
	-- {quest:84201} Saving the Best for Last · {item:16698} Dreadmist Mask · {npc:1853} Darkmaster Gandling · {area:2057} Scholomance · {item:16700} Dreadmist Robe · {npc:10363} General Drakkisath
	["{quest:84201} takes your {item:16698}: {npc:1853} in {area:2057} (about 12%), and your {item:16700}: {npc:10363} in Upper Blackrock Spire (about 12%)."] = "{quest:84201} nimmt dein {item:16698}: {npc:1853} in {area:2057} (etwa 12 %), und dein {item:16700}: {npc:10363} in der Oberen Schwarzfelsspitze (etwa 12 %).",

	-- Step 61: Mokvar: Saving the Best for Last
	-- {quest:84209} Saving the Best for Last · {item:16698} Dreadmist Mask · {npc:1853} Darkmaster Gandling · {area:2057} Scholomance · {item:16700} Dreadmist Robe · {npc:10363} General Drakkisath
	["{quest:84209} takes your {item:16698}: {npc:1853} in {area:2057} (about 12%), and your {item:16700}: {npc:10363} in Upper Blackrock Spire (about 12%)."] = "{quest:84209} nimmt dein {item:16698}: {npc:1853} in {area:2057} (etwa 12 %), und dein {item:16700}: {npc:10363} in der Oberen Schwarzfelsspitze (etwa 12 %).",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["Alliance Warlocks: Polestar's quest data doesn't know Forever's {quest:84193} for you yet, so the guide stops here for you until it does. Take it from {npc:16016} and give {npc:230319} your three pieces. {npc:230319} then sends you to {npc:16033}'s ghost in {area:254} (Ghost Revealer): {quest:8961}, your class's two components and two summons, {area:2079}, {quest:8994} and {npc:16042} in Upper Blackrock Spire, then back to her for Saving the Best for Last, which takes your {item:16698} and {item:16700}."] = "Allianz-Hexenmeister: Die Questdaten von Polestar kennen {quest:84193} von Forever für dich noch nicht, daher endet der Guide für dich hier, bis sie es tun. Nimm die Quest bei {npc:16016} an und gib {npc:230319} deine drei Teile. {npc:230319} schickt dich dann zum Geist von {npc:16033} in {area:254} (Geisterenthüller): {quest:8961}, die zwei Komponenten und zwei Beschwörungen deiner Klasse, {area:2079}, {quest:8994} und {npc:16042} in der Oberen Schwarzfelsspitze, dann zurück zu ihr für „Das Beste zum Schluss“, die dir {item:16698} und {item:16700} abnimmt.",
	-- ["Back to {npc:16016} at {area:2279}'s gate (Ghost Revealer). {quest:84193} takes your {item:16704}: {npc:10436} in {area:2279} (about 18%), your {item:16699}: {npc:10440} in {area:2279} (about 10%), and your {item:16701}: {npc:10503} in {area:2057} (about 17%)."] = "Zurück zu {npc:16016} am Tor von {area:2279} (Geisterenthüller). {quest:84193} nimmt dein {item:16704}: {npc:10436} in {area:2279} (etwa 18 %), dein {item:16699}: {npc:10440} in {area:2279} (etwa 10 %), und dein {item:16701}: {npc:10503} in {area:2057} (etwa 17 %).",
	-- ["Polestar's quest data doesn't know Forever's Saving the Best for Last for the {npc:235043} yet, so this guide can't track it: {npc:230317} should offer it now. Take it from him and give him your {item:16698} and {item:16700}."] = "Die Questdaten von Polestar kennen Forevers Das Beste kommt zum Schluss für {npc:235043} noch nicht, daher kann dieser Guide es nicht verfolgen: {npc:230317} sollte es dir jetzt anbieten. Nimm es bei ihm an und gib ihm dein {item:16698} und {item:16700}.",
	-- ["Saving the Best for Last takes your {item:16698}: {npc:1853} in {area:2057} (about 12%), and your {item:16700}: {npc:10363} in Upper Blackrock Spire (about 12%)."] = "Das Beste kommt zum Schluss nimmt dein {item:16698}: {npc:1853} in {area:2057} (etwa 12 %), und dein {item:16700}: {npc:10363} in der Oberen Schwarzfelsspitze (etwa 12 %).",
	-- ["{npc:230317}: Saving the Best for Last"] = "{npc:230317}: Das Beste zum Schluss",
